<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Snake</title>
<style>
  body { margin:0; background:#111; overflow:hidden; font-family:sans-serif; color:#0f0; }
  #score { position:absolute; top:10px; left:10px; font-size:20px; }
  canvas { display:block; margin:auto; background:#222; }
</style>
</head>
<body>
<div id="score">Score: 0</div>
<canvas id="game"></canvas>
<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const size = 20;                 // size of each grid cell
  const cols = Math.floor(window.innerWidth / size);
  const rows = Math.floor(window.innerHeight / size);
  canvas.width = cols * size;
  canvas.height = rows * size;

  let snake = [{x: Math.floor(cols/2), y: Math.floor(rows/2)}];
  let dir = {x: 0, y: 0};
  let food = randomFood();
  let score = 0;
  const speed = 100; // ms per step

  function randomFood() {
    let f;
    do {
      f = {x: Math.floor(Math.random()*cols), y: Math.floor(Math.random()*rows)};
    } while (snake.some(s => s.x===f.x && s.y===f.y));
    return f;
  }

  function setDirection() {
    // Simple greedy approach: move horizontally if needed, else vertically.
    const head = snake[0];
    const dx = food.x - head.x;
    const dy = food.y - head.y;
    // Prefer horizontal move unless it leads to immediate collision
    if (dx !== 0) {
      const ndir = {x: dx>0?1:-1, y:0};
      if (!willCollide(ndir)) { dir = ndir; return; }
    }
    if (dy !== 0) {
      const ndir = {x:0, y: dy>0?1:-1};
      if (!willCollide(ndir)) { dir = ndir; return; }
    }
    // If both blocked, try any safe direction
    const dirs = [{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}];
    for (const d of dirs) {
      if (!willCollide(d)) { dir = d; return; }
    }
    // No safe move – keep current (will cause game over)
  }

  function willCollide(testDir) {
    const nx = snake[0].x + testDir.x;
    const ny = snake[0].y + testDir.y;
    // wall
    if (nx < 0 || ny < 0 || nx >= cols || ny >= rows) return true;
    // self
    return snake.some(s => s.x===nx && s.y===ny);
  }

  function step() {
    setDirection();
    const newHead = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

    // Check collisions
    if (newHead.x < 0 || newHead.y < 0 || newHead.x >= cols || newHead.y >= rows ||
        snake.some(s => s.x===newHead.x && s.y===newHead.y)) {
      // Game over – reset
      snake = [{x: Math.floor(cols/2), y: Math.floor(rows/2)}];
      dir = {x:0,y:0};
      score = 0;
      document.getElementById('score').textContent = 'Score: 0';
      food = randomFood();
      return;
    }

    snake.unshift(newHead);
    if (newHead.x===food.x && newHead.y===food.y) {
      score++;
      document.getElementById('score').textContent = 'Score: ' + score;
      food = randomFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function draw() {
    ctx.fillStyle = '#222';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    // food
    ctx.fillStyle = '#f00';
    ctx.fillRect(food.x*size, food.y*size, size, size);
    // snake
    ctx.fillStyle = '#0f0';
    snake.forEach(seg => ctx.fillRect(seg.x*size, seg.y*size, size, size));
  }

  setInterval(step, speed);
})();
</script>
</body>
</html>
```
The script repeatedly chooses the direction that reduces the distance to the food while avoiding imminent collisions, moves the neon‑green snake accordingly, grows it on food, updates the score, and redraws the dark‑background canvas.
